import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    arr = []
    for _ in range(n):
        try:
            arr.append(int(next(iterator)))
        except StopIteration:
            break

    freq_map = Counter(arr)

    stack = []
    result = [-1] * n

    for i in range(n - 1, -1, -1):
        current_val = arr[i]
        current_freq = freq_map[current_val]

        while stack:
            top_val = stack[-1]
            top_freq = freq_map[top_val]

            if top_freq > current_freq:
                result[i] = top_val
                break
            else:
                stack.pop()

        stack.append(current_val)

    print(*(result))

if __name__ == "__main__":
    solve()
